// ELEMENTS:
// 1. Navy liso com o filete vermelho no topo
// 2. Dois ícones em traço fino que se desenham: guardar (marcador) e partilhar (três nós ligados)
// 3. Frase (anim.text) em Light com **palavras** em Heavy, traço vermelho, sub em névoa
// 4. Marca (brand) em DM Mono, pequena, no fundo; grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const MIST = "#C9D3E3";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.28) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.08, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const GuardarPartilhar: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const sub = String(p.sub ?? "").trim();
  const brand = String(p.brand ?? "").trim();
  const parts = String(anim.text ?? "").split(/(\*\*[^*]+\*\*)/).filter(Boolean);

  const show = (delay: number, len = 0.7): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const rise = (delay: number): React.CSSProperties => {
    const t = show(delay);
    return { opacity: t, transform: `translateY(${(1 - t) * 26 * u}px)` };
  };
  const stroke = { fill: "none", stroke: WHITE, strokeWidth: 2.6, strokeLinecap: "round" as const, strokeLinejoin: "round" as const, pathLength: 1, strokeDasharray: 1 };

  return (
    <AbsoluteFill style={{ backgroundColor: NAVY, overflow: "hidden" }}>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", flexDirection: "column", textAlign: "center", padding: `0 ${90 * u}px`, gap: 54 * u }}>
        <div style={{ display: "flex", gap: 90 * u }}>
          <svg width={170 * u} height={170 * u} viewBox="0 0 120 120">
            <path d="M34 14 H86 V106 L60 86 L34 106 Z" {...stroke} strokeDashoffset={1 - show(0.1, 1.1)} />
          </svg>
          <svg width={170 * u} height={170 * u} viewBox="0 0 120 120">
            <path d="M40 54 L80 30 M40 66 L80 90" {...stroke} strokeDashoffset={1 - show(0.6, 0.8)} />
            {[[30, 60], [88, 26], [88, 94]].map(([cx, cy], i) => (
              <circle key={i} cx={cx} cy={cy} r={12} fill={i === 0 ? RED : "none"} stroke={i === 0 ? RED : WHITE} strokeWidth={2.6} opacity={show(0.4 + i * 0.2, 0.4)} />
            ))}
          </svg>
        </div>
        <div style={{ fontFamily: FONTS.display, fontSize: 120 * u, lineHeight: 1.05, color: WHITE, ...rise(0.7) }}>
          {parts.map((s, i) => <span key={i} style={{ fontWeight: s.startsWith("**") ? 800 : 300 }}>{s.replace(/\*\*/g, "")}</span>)}
        </div>
        <div style={{ width: show(1.0, 0.7) * 110 * u, height: 3 * u, background: RED }} />
        {sub ? <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 54 * u, lineHeight: 1.2, color: MIST, maxWidth: 880 * u, ...rise(1.2) }}>{sub}</div> : null}
      </AbsoluteFill>
      {brand ? (
        <div style={{ position: "absolute", bottom: 150 * u, left: 0, right: 0, textAlign: "center", fontFamily: FONTS.mono, fontSize: 30 * u, letterSpacing: "0.3em", color: WHITE, opacity: show(1.6) }}>{brand}</div>
      ) : null}
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default GuardarPartilhar;
